func TestGLS254UpstreamVectors(t *testing.T) {
	// Generated by the original, separately compiled jbms adapter, not this
	// cache/batch adapter. Freeze the exact map and compressed byte convention.
	b := &glsBackend{}
	for _, v := range [][2]string{
		{"", "cc833aab21783acead1a8d3e1d14af7355337bea98ef168cd6a23ce991cb033b"},
		{"hello", "ba9b2a048fa017e111f10e1d124c1e6f7593d5884bf08951527ffa3797c8f01c"},
		{"world", "63dbe723d017ea4e7783f2fc67298f4b5980f704707fb48e811dcc55f3cda6e4"},
		{"incauth-gls254-vector", "205741c2ca6e7b4a248df60636b1d21a8f0c6b146ad6778d43a890f9827bcf4a"},
	} {
		got, err := b.Apply(nil, nil, [][]byte{[]byte(v[0])})
		if err != nil || hex.EncodeToString(got) != v[1] {
			t.Fatalf("upstream map mismatch %q: %x %v", v[0], got, err)
		}
		zero, err := b.Apply(got, [][]byte{[]byte(v[0])}, nil)
		if err != nil || !bytes.Equal(zero, make([]byte, 32)) {
			t.Fatal("inverse", err)
		}
	}
}

func TestGLS254CheckedCodec(t *testing.T) {
	b := &glsBackend{}
	for _, sign := range []byte{0, 128} {
		raw := make([]byte, 32)
		raw[31] = sign // Infinity and order-2 point: full curve group, not R255.
		got, err := b.Apply(raw, nil, nil)
		if err != nil || !bytes.Equal(got, raw) {
			t.Fatal("canonical exceptional point", sign, err)
		}
		raw[15] = 128 // Unused field bit must not be silently discarded.
		if b.Validate(raw) == nil {
			t.Fatal("noncanonical field element accepted")
		}
	}
	accepted := 0
	for i := 0; i < 4096; i++ {
		raw := sha256.Sum256([]byte(fmt.Sprintf("gls-decode/%d", i)))
		if b.Validate(raw[:]) != nil {
			continue
		}
		accepted++
		got, err := b.Apply(raw[:], nil, nil)
		if err != nil || !bytes.Equal(got, raw[:]) {
			t.Fatal("canonical roundtrip", i, err)
		}
	}
	if accepted == 0 || accepted == 4096 {
		t.Fatal("random decoder test did not exercise both paths")
	}
}

func TestGLS254SharedCacheConcurrency(t *testing.T) {
	cache, _ := NewComputationCache(1, "unified")
	var wg sync.WaitGroup
	for worker := 0; worker < 16; worker++ {
		wg.Add(1)
		go func(worker int) {
			defer wg.Done()
			kind := uint8(worker % 2)
			plain, err := NewScheme(GLS254, kind)
			if err != nil {
				t.Error(err)
				return
			}
			cached := plain.WithCache(cache)
			var children [16]Child
			for i := range children {
				children[i] = Child{true, Commitment{byte(i + 1)}}
			}
			state, _, err := cached.Build(children)
			if err != nil {
				t.Error(err)
				return
			}
			for round := 0; round < 300; round++ {
				slot := uint8(round % 16)
				next := Child{true, Commitment(sha256.Sum256([]byte(fmt.Sprintf("%d/%d", worker, round))))}
				old := append([]byte(nil), state...)
				got, root, _, err := cached.Update(state, 65535, []Change{{slot, children[slot], next}})
				if err != nil {
					t.Error(err)
					return
				}
				children[slot] = next
				want, wantRoot, err := plain.Build(children)
				if err != nil || !bytes.Equal(want, got) || root != wantRoot || !bytes.Equal(state, old) {
					t.Error("cache ownership/domain/concurrency mismatch", err)
					return
				}
				state = got
			}
		}(worker)
	}
	wg.Wait()
	st := cache.Stats()
	if st.AccountedBytes > st.CapacityBytes || st.AccumulatorHits == 0 || st.ContributionHits == 0 || st.Evictions == 0 {
		t.Fatalf("cache paths/budget not exercised: %+v", st)
	}
}

// Whole Scheme.Update, including the actual unified LRU, framing, CGO and final
// Keccak. New child commitments vary every iteration; no artificial all-hit map.
func BenchmarkAuthenticationBackend(b *testing.B) {
	for _, id := range []string{Ristretto255, GLS254} {
		for _, dirty := range []int{1, 4} {
			for _, mode := range []string{"off", "accumulator", "contribution", "unified"} {
				b.Run(fmt.Sprintf("%s/dirty%d/%s", id, dirty, mode), func(b *testing.B) {
					s, err := NewScheme(id, Storage)
					if err != nil {
						b.Fatal(err)
					}
					if mode != "off" {
						cache, _ := NewComputationCache(4096, mode)
						s = s.WithCache(cache)
					}
					var children [16]Child
					for i := range children {
						children[i] = Child{true, Commitment{byte(i + 1)}}
					}
					state, _, err := s.Build(children)
					if err != nil {
						b.Fatal(err)
					}
					changes := make([]Change, dirty)
					b.ReportAllocs()
					b.ResetTimer()
					for j := 0; j < b.N; j++ {
						for i := range changes {
							slot := (j + i) % 16
							next := Child{Present: true}
							binary.BigEndian.PutUint64(next.C[:8], uint64(j+100))
							next.C[8] = byte(slot)
							changes[i] = Change{uint8(slot), children[slot], next}
							children[slot] = next
						}
						state, _, _, err = s.Update(state, 65535, changes)
						if err != nil {
							b.Fatal(err)
						}
					}
				})
			}
		}
	}
}
